SRC = [("TTB: Established American Viticultural Areas", "https://www.ttb.gov/wine/established-avas"),
       ("UC Davis Library AVA Digitizing Project", "https://github.com/UCDavisLibrary/ava"),
       ("Wikipedia: Oregon wine", "https://en.wikipedia.org/wiki/Oregon_wine"),
       ("Wikipedia: Eyrie Vineyards", "https://en.wikipedia.org/wiki/Eyrie_Vineyards"),
       ("Federal Register, Tualatin Hills and Laurelwood District final rule (2020)", "https://www.federalregister.gov/documents/2020/06/03/2020-10919"),
       ("Federal Register, Lower Long Tom final rule (2021)", "https://www.federalregister.gov/documents/2021/11/10/2021-23979"),
       ("Federal Register, Mount Pisgah, Polk County, Oregon final rule (2022)", "https://www.federalregister.gov/documents/2022/06/03/2022-11715")]
W, SO, OR = "Willamette Valley", "Southern Oregon", "Oregon"
regions = [
 region("us", OR, 44.3, -121.5, 6.4,
 "America's Pinot Noir state, built by small growers who ignored the experts.",
 "Oregon has more than 1,100 wineries and roughly 44,000 acres of vines (2022 census), fourth in the US by production after California, Washington and New York, and more than half the acreage is Pinot Noir. Almost everything important happens west of the Cascades in the Willamette Valley, a cool, rainy valley that the University of California's professors told the first growers was too cold for wine. Southern Oregon is warmer and more varied; the Columbia Gorge, Walla Walla and Snake River Valley AVAs reach into the dry interior.\n\nOregon's identity is small, family-owned, sustainability-minded and Burgundian. The state's labeling law is stricter than federal rules: most varietal wines must be at least 90 percent of the named grape (federal minimum 75 percent), and vintage-dated AVA wines need 95 percent from the AVA.",
 "Henderson Luelling brought grapevines to Oregon Territory over the Oregon Trail in 1847, and Peter Britt opened Valley View winery at Jacksonville in 1852. Prohibition and its aftermath left the industry dormant for decades. In 1961 Richard Sommer planted Riesling at HillCrest in the Umpqua Valley, Oregon's oldest continuously operating estate winery. Then a group of mostly Californian dropouts arrived: David Lett (The Eyrie Vineyards, first Pinot Noir in the Willamette Valley in 1965 and 1966), Charles Coury, Dick Erath, David Adelsheim, Dick Ponzi and the Sokol Blossers.\n\nIn 1979 Eyrie's 1975 South Block Reserve Pinot Noir placed among the top Pinots at the Gault-Millau 'Wine Olympics' in Paris; at Robert Drouhin's 1980 rematch in Beaune it finished a close second to his 1959 Chambolle-Musigny. Drouhin bought land in the Dundee Hills and opened Domaine Drouhin Oregon in 1988. Since then Burgundian families (Lafon, Louis Jadot, Bouchard via Henriot, Lingua Franca with Dominique Lafon) and Californian and Champagne companies have invested heavily.",
 "Marine-influenced, cool and wet in winter, dry and warm in summer; the Coast Range shelters the Willamette Valley from Pacific storms, while the Van Duzer Corridor lets cooling winds in. The Willamette's three key soil families are volcanic Jory (from Columbia River basalt flows about 15 million years ago), marine sedimentary soils (Willakenzie and relatives) and wind-blown Laurelwood loess. Southern Oregon is warmer and drier with very old, varied geology.",
 "Pinot Noir dominates, then Pinot Gris, Chardonnay, Riesling, Syrah, Cabernet Sauvignon, Tempranillo, Merlot and Gamay.",
 "Pinot Noir of perfume and acidity; increasingly serious Chardonnay; Pinot Gris; sparkling wine; Tempranillo and Syrah from the south.",
 "Federal AVAs plus stricter state rules: most varietals need 90 percent of the stated grape; AVA wines need 95 percent of grapes from that AVA. Oregon has 23 AVAs wholly or partly in the state.",
 ["Willamette Valley", "Southern Oregon", "Columbia Gorge", "Walla Walla Valley", "The Rocks District of Milton-Freewater", "Snake River Valley", "Columbia Valley"], SRC, parent=None),
 region("us", W, 45.0, -123.1, 8.6,
 "A cool, green valley between the Coast Range and the Cascades where Oregon proved it could grow great Pinot Noir.",
 "The Willamette Valley AVA (1983) runs about 240 km from the Columbia River near Portland south to Eugene and holds roughly two-thirds of Oregon's vineyards and most of its wineries. Vineyards sit on the foothills and isolated hill groups on the valley's west side, mostly between 60 and 300 m, above the frost-prone valley floor and the old flood sediments. It is subdivided into 11 nested AVAs, each defined largely by soil and exposure to Pacific wind.",
 "See Oregon: Eyrie (1965 to 1966), Erath, Adelsheim, Ponzi, Sokol Blosser and the Drouhins set the pattern. The valley floor's sediments came from the Missoula Floods, ice-age deluges that backed up the Willamette and dropped erratic boulders from Montana; vineyards prefer the older hillside soils above them.",
 "Three soil families shape style: volcanic Jory (red, iron-rich, from Columbia River basalt) in the Dundee Hills, Eola-Amity Hills and parts of the Chehalem Mountains; marine sedimentary soils (Willakenzie) in Yamhill-Carlton and Ribbon Ridge; and wind-blown loess (Laurelwood) in the Chehalem Mountains and Tualatin Hills. Ocean wind through the Van Duzer Corridor cools the western side every afternoon.",
 "Pinot Noir (the majority), Chardonnay, Pinot Gris, Pinot Blanc, Riesling, Gamay.",
 "Pinot Noir of red-fruit perfume and silky texture; Chardonnay of tension; traditional-method sparkling wine.",
 "Willamette Valley AVA plus 11 sub-AVAs (2004 to 2022).",
 ["Willamette Valley", "Dundee Hills", "Eola-Amity Hills", "Chehalem Mountains", "Ribbon Ridge", "Laurelwood District", "Yamhill-Carlton", "McMinnville", "Van Duzer Corridor", "Tualatin Hills", "Lower Long Tom", "Mount Pisgah, Polk County, Oregon"], SRC, parent=OR),
 region("us", SO, 42.8, -123.2, 8.0,
 "Warm valleys under old mountains: Tempranillo, Syrah and Bordeaux varieties alongside Pinot Noir.",
 "Southern Oregon (2004) joins the Umpqua and Rogue valleys, both warmer and drier than the Willamette. The Klamath Mountains and Coast Range here contain some of the oldest and most varied rocks in Oregon, and the climate ranges from cool, Pacific-influenced Elkton to the hot, dry Rogue Valley near Medford. Abacela's Earl and Hilda Jones planted Tempranillo in the Umpqua in 1995, and Syrah, Grenache, Albariño, Viognier, Cabernet and Merlot all grow well.",
 "Peter Britt founded Valley View winery at Jacksonville in 1852, and Richard Sommer's HillCrest (1961) near Roseburg restarted Oregon wine after Prohibition.",
 "Complex geology: marine sediments, volcanic and metamorphic rocks; warm, dry summers with big day-night swings.",
 "Pinot Noir, Syrah, Tempranillo, Cabernet Sauvignon, Merlot, Chardonnay, Viognier, Albariño, Grenache.",
 "Warm-climate reds and aromatic whites; cool-climate Pinot Noir from Elkton.",
 "Southern Oregon contains Umpqua Valley (with Elkton Oregon and Red Hill Douglas County, Oregon) and Rogue Valley (with Applegate Valley).",
 ["Southern Oregon", "Umpqua Valley", "Elkton Oregon", "Red Hill Douglas County, Oregon", "Rogue Valley", "Applegate Valley"], SRC, parent=OR)]

A = []
A.append(ava("Willamette Valley", W, "Oregon's flagship AVA (1983, expanded 2016) of about 3.4 million acres, with most of the state's wineries and vineyards. Cool, wet winters and dry summers, with a long, mild ripening period in September and October, give Pinot Noir of red-fruit perfume, silk and bright acidity. Chardonnay has become a second calling card since the 2010s, made in a leaner, reductive style.", sub="Oregon", styles=["red", "white", "sparkling", "rose"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris, Pinot Blanc, Riesling, Gamay", producers=["The Eyrie Vineyards", "Domaine Drouhin Oregon", "Beaux Frères", "Bergström", "Cristom", "Evening Land", "Antica Terra", "Adelsheim", "Ponzi", "Domaine Serene"], contains=["Dundee Hills", "Eola-Amity Hills", "Chehalem Mountains", "Ribbon Ridge", "Laurelwood District", "Yamhill-Carlton", "McMinnville", "Van Duzer Corridor", "Tualatin Hills", "Lower Long Tom", "Mount Pisgah, Polk County, Oregon"]))
A.append(ava("Dundee Hills", W,
 "The birthplace of Oregon Pinot Noir and still its most famous address (2004). The Dundee Hills are a compact block of hills above the town of Dundee, and the AVA boundary follows the 200-foot contour, roughly where red volcanic Jory soil begins. Jory is deep, iron-rich, red clay loam weathered from Columbia River basalt that flowed here about 15 million years ago; it drains well and holds enough water for dry farming.\n\nDavid and Diana Lett planted the first Pinot Noir in the Willamette Valley at their Eyrie Vineyards site in the Dundee Hills in 1965 to 1966, and Erath, Sokol Blosser, Domaine Drouhin Oregon (1988), Archery Summit, Domaine Serene and Lingua Franca followed. Dundee Hills Pinot Noir is classically red-fruited and perfumed, with silky tannin and a hint of earth and spice.",
 sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris",
 terroir="Volcanic Jory soils on southeast-facing slopes above 200 feet; protected from the worst Pacific winds by the Coast Range.",
 producers=["The Eyrie Vineyards", "Domaine Drouhin Oregon", "Sokol Blosser", "Erath", "Archery Summit", "Domaine Serene", "Lingua Franca", "Maison Joseph Drouhin", "Winderlea"],
 nerd="Jory soil is Oregon's official state soil, named after Jory Hill near Salem."))
A.append(ava("Eola-Amity Hills", W, "A north-south ridge (2006) northwest of Salem, directly in line with the Van Duzer Corridor, so cold ocean wind blows across it most summer afternoons. The wind keeps acidity high and skins thick; the soils are thin volcanic basalt with some marine sediment. Eola-Amity Pinot Noir is dark-fruited, firm and taut, and Chardonnay is among Oregon's best. Bethel Heights (1977) and Cristom were pioneers; Evening Land's Seven Springs Vineyard is famous.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris", producers=["Bethel Heights", "Cristom", "Evening Land (Seven Springs)", "St. Innocent", "Lingua Franca (Eola sourcing)", "Walter Scott", "Brick House (nearby)"]))
A.append(ava("Chehalem Mountains", W, "The highest landform in the northern Willamette Valley (2006), a 30 km ridge southwest of Portland rising to about 500 m at Bald Peak. It has all three Willamette soil types: volcanic Jory, marine sediments and wind-blown Laurelwood loess. Adelsheim (1971) and Ponzi were early settlers; the AVA contains Ribbon Ridge and the Laurelwood District.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris, Pinot Blanc", producers=["Adelsheim", "Ponzi", "Bergström", "Rex Hill", "Penner-Ash (nearby)"], contains=["Ribbon Ridge", "Laurelwood District"]))
A.append(ava("Ribbon Ridge", W, "A tiny ridge (2005) about 5.6 km long within the Chehalem Mountains, made of uplifted ocean sediments (Willakenzie soils) and sheltered by the larger mountains. At approval it had 14 vineyards on 286 acres. Beaux Frères (founded in 1986 by Mike Etzel with his brother-in-law Robert Parker) and Patricia Green made it famous for dark, dense Pinot Noir.", sub="Chehalem Mountains", styles=["red"], dom="red", grapes="Pinot Noir, Chardonnay", producers=["Beaux Frères", "Patricia Green", "Brick House", "Trisaetum"]))
A.append(ava("Laurelwood District", W, "A sub-AVA (2020) of about 33,600 acres on the northern and eastern slopes of the Chehalem Mountains, defined by Laurelwood soil: wind-blown loess deposited after the Missoula Floods over basalt. At approval it had about 70 vineyards (975 acres) and 25 wineries. Laurelwood Pinot Noir tends to be lifted and spicy.", sub="Chehalem Mountains", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris", producers=["Ponzi", "Adelsheim (part)", "Alloro"]))
A.append(ava("Yamhill-Carlton", W, "A horseshoe of low foothills (2004, boundary refined 2010) around the towns of Yamhill and Carlton, limited to elevations between 200 and 1,000 feet. Coarse-grained, ancient marine sediments (Willakenzie) drain quickly, and vines ripen early; the Pinot Noirs are dark-fruited and broad-shouldered. The AVA was approved as 'Yamhill-Carlton District' and later shortened.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris", producers=["Ken Wright", "Soter", "Shea Wine Cellars", "Elk Cove", "Anne Amie", "WillaKenzie"], nerd="Ken Wright's Carlton winery helped turn the town into a tasting-room hub; Shea Vineyard is one of Oregon's most bottled single vineyards."))
A.append(ava("McMinnville", W, "A sub-AVA (2005) in the Coast Range foothills west and southwest of McMinnville, limited to elevations of 200 to 1,000 feet, with uplifted marine sediments and basalt. Close to the Van Duzer Corridor, it is cool and windy, and the Pinot Noirs are dark and firmly structured. Eyrie's winery is in town, though its vineyards are in the Dundee Hills.", sub="Willamette Valley", styles=["red"], dom="red", grapes="Pinot Noir, Pinot Gris, Chardonnay", producers=["Brittan", "Youngberg Hill", "Maysara"]))
A.append(ava("Van Duzer Corridor", W, "A low gap through the Coast Range (2018) about 59,900 acres in size, through which cold Pacific air flows into the Willamette Valley every summer afternoon, dropping temperatures fast. The AVA covers the valley floor and foothills where that wind hits hardest; at approval it had 17 vineyards on about 1,000 acres. Pinot Noir from here has thick skins, dark colour and high acidity.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Pinot Gris", producers=["Johan", "Cherry Hill", "Left Coast"], nerd="The wind is so reliable that growers call it the 'Van Duzer winds'; TTB clarified Eola-Amity Hills' boundary when it created this AVA."))
A.append(ava("Tualatin Hills", W, "The northwestern corner of the Willamette Valley (2020), about 144,000 acres in the hills west of Portland around Forest Grove, Gaston and Hillsboro. Laurelwood loess soils, higher rainfall and cooler temperatures than further south. At approval it had 33 vineyards and 21 wineries, including David Hill and Ernest Reuter's historic Forest Grove plantings.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay, Riesling, Pinot Gris", producers=["Ruby Vineyard", "David Hill", "Montinore", "Elk Cove (part)"]))
A.append(ava("Lower Long Tom", W, "The southernmost Willamette sub-AVA (2021), about 25,000 acres in the hills west of the Long Tom River near Monroe, between Eugene and Corvallis. Thin, uplifted marine sedimentary soils (Bellpine and Bellpine/Jory) and a slightly warmer climate. At approval it had 22 vineyards (492 acres) and 10 wineries.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Pinot Gris, Chardonnay", producers=["Benton-Lane", "High Pass", "Brigadoon"]))
A.append(ava("Mount Pisgah, Polk County, Oregon", W, "A small AVA (2022) of about 5,850 acres around Mount Pisgah, a hill west of Salem near the town of Dallas. Its soils come from Siletz River volcanics, basalt about 40 to 60 million years old and much older than the Jory of the Dundee Hills. At approval it had 10 vineyards (531 acres) and two wineries, including Freedom Hill Vineyard, a famous source of Pinot Noir.", sub="Willamette Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Chardonnay", producers=["Freedom Hill (grower)", "Ken Wright (Freedom Hill)", "Bethel Heights (sourcing)"]))
A.append(ava("Southern Oregon", SO, "Umbrella AVA (2004) joining the Umpqua and Rogue valleys, created so wines blended across them could carry a regional name. At approval it had about 120 vineyards, 3,000 acres and 17 wineries.", sub="Oregon", styles=["red", "white"], dom="red", grapes="Pinot Noir, Syrah, Tempranillo, Cabernet Sauvignon, Merlot, Chardonnay, Viognier", contains=["Umpqua Valley", "Rogue Valley"]))
A.append(ava("Umpqua Valley", SO, "The 'hundred valleys of the Umpqua' (1984) around Roseburg, a tangle of small valleys where the Klamath Mountains, Cascades and Coast Range meet. It has the most varied geology in Oregon and a climate between the cool Willamette and the warm Rogue. Richard Sommer's HillCrest (1961) restarted Oregon wine here, and Abacela planted the Pacific Northwest's first Tempranillo in 1995.", sub="Southern Oregon", styles=["red", "white"], dom="red", grapes="Pinot Noir, Tempranillo, Syrah, Albariño, Riesling", producers=["Abacela", "HillCrest", "Reustle", "Girardet"], contains=["Elkton Oregon", "Red Hill Douglas County, Oregon"]))
A.append(ava("Elkton Oregon", SO, "The coolest and wettest part of the Umpqua (2013), about 74,900 acres along the Umpqua River near Elkton, only about 50 km from the Pacific, so marine air flows straight up the river. It is cool-climate Pinot Noir, Riesling and Gewürztraminer country, cooler than much of the Willamette.", sub="Umpqua Valley", styles=["red", "white"], dom="red", grapes="Pinot Noir, Riesling, Gewürztraminer, Chardonnay", producers=["Brandborg", "Bradley", "River's Edge"]))
A.append(ava("Red Hill Douglas County, Oregon", SO, "One of Oregon's smallest AVAs (2005), about 5,500 acres around a single hill near Yoncalla in the northern Umpqua, with red, Jory-type volcanic soil similar to the Dundee Hills. Essentially one large vineyard; Pinot Noir.", sub="Umpqua Valley", styles=["red"], dom="red", grapes="Pinot Noir"))
A.append(ava("Rogue Valley", SO, "A large, warm valley system (1991) around Medford and Grants Pass along the Rogue River and its tributaries (Applegate, Illinois, Bear Creek). The eastern part around Ashland is high and continental; the west is wetter. Syrah, Tempranillo, Cabernet, Merlot and Viognier thrive; Peter Britt's Valley View (1852) at Jacksonville was Oregon's first recorded winery.", sub="Southern Oregon", styles=["red", "white"], dom="red", grapes="Syrah, Cabernet Sauvignon, Merlot, Tempranillo, Viognier, Chardonnay, Pinot Noir", producers=["Valley View", "Troon (Applegate)", "Weisinger", "RoxyAnn", "Kriselle"], contains=["Applegate Valley"]))
A.append(ava("Applegate Valley", SO, "A sub-AVA (2000) of the Rogue Valley along the Applegate River, warm and dry with decomposed granite and alluvial soils. Small family wineries grow Syrah, Zinfandel, Viognier and Rhône and Bordeaux varieties; Troon converted to biodynamic farming.", sub="Rogue Valley", styles=["red", "white"], dom="red", grapes="Syrah, Zinfandel, Viognier, Cabernet Sauvignon, Vermentino", producers=["Troon", "Cowhorn", "Wooldridge Creek", "Red Lily"]))
A.append(ava("Columbia Gorge", "Columbia Gorge", "A dramatic AVA (2004) straddling the Columbia River where it cuts through the Cascade Range, on both the Oregon (Hood River, Wasco) and Washington (Klickitat, Skamania) sides. In about 65 km, rainfall falls from more than 90 cm a year in the west to under 25 cm in the east, so the gorge grows everything from cool-climate Pinot Noir, Chardonnay and Gewürztraminer near Hood River to Zinfandel, Syrah and Cabernet near The Dalles. Old Zinfandel planted by Italian immigrants survives at The Pines 1852 vineyard.", sub="Oregon and Washington", styles=["red", "white", "sparkling"], dom="white", grapes="Pinot Noir, Chardonnay, Gewürztraminer, Riesling, Syrah, Zinfandel", producers=["Analemma", "Syncline", "Phelps Creek", "Cathedral Ridge", "The Pines 1852"]))
A.append(ava("The Rocks District of Milton-Freewater", "Walla Walla Valley", "The only AVA in the United States defined almost entirely by a single soil feature (2015). It sits on the Oregon side of the Walla Walla Valley, on the alluvial fan of the Walla Walla River, where the ground is a jumble of rounded basalt cobbles (Freewater cobbly loam) that store heat and radiate it at night. At approval it had about 250 acres of vines on 3,770 acres.\n\nChristophe Baron, a Champenois, spotted the stones in 1996 and planted Cayuse; the Syrahs from The Rocks have a savoury, olive, smoked-meat and iron character often compared to the northern Rhône, sometimes called 'funk' by fans.", sub="Walla Walla Valley", styles=["red"], dom="red", grapes="Syrah, Grenache, Cabernet Sauvignon, Merlot, Tempranillo", producers=["Cayuse", "Horsepower", "Hors Catégorie", "Reynvaan", "Saviah", "Delmas", "Rotie"], nerd="The AVA was the first in the US whose petition rested almost wholly on soil; it is entirely within Oregon, yet nearly all the wineries that use it are across the state line in Walla Walla, Washington."))

S = []
S.append(site("eyrie-vineyards", "us", "The Eyrie Vineyards (original vineyard)", "vineyard", "Dundee Hills", 45.2560, -123.0600,
 "David and Diana Lett planted Oregon's first Willamette Valley Pinot Noir here in 1965 to 1966 against the advice of UC Davis. The 1975 South Block Reserve stunned French judges at the 1979 Gault-Millau tasting and in Drouhin's 1980 rematch. Eyrie also made the first Pinot Gris in the United States.", cls="Planted 1965 to 1966", q="approx", producers=["The Eyrie Vineyards"]))
S.append(site("eyrie-winery", "us", "The Eyrie Vineyards winery", "estate", "Willamette Valley", 45.2141, -123.1879,
 "The Letts' winery in a converted turkey-processing plant in McMinnville, where Jason Lett now makes wine from his parents' old, own-rooted Dundee Hills vines. The family still releases older vintages from its library, showing how long Willamette Pinot Noir and Pinot Gris can age.", producers=["The Eyrie Vineyards"]))
S.append(site("domaine-drouhin-oregon", "us", "Domaine Drouhin Oregon", "estate", "Dundee Hills", 45.2655, -123.0556,
 "Robert Drouhin of Beaune, impressed by Eyrie's showing in 1979 and 1980, bought land in the Dundee Hills and opened this multi-level gravity-flow winery in 1988, the first major Burgundian investment in Oregon. Véronique Drouhin-Boss makes the wines.", cls="Founded 1987 to 1988", producers=["Domaine Drouhin Oregon"]))
S.append(site("sokol-blosser", "us", "Sokol Blosser", "estate", "Dundee Hills", 45.2519, -123.0496,
 "Bill Sokol Blosser and Susan Sokol Blosser planted in the Dundee Hills in 1971; in 2002 their winery was the first in the US to earn LEED certification for a green building.", cls="Founded 1971", producers=["Sokol Blosser"]))
S.append(site("hillcrest", "us", "HillCrest Vineyard", "estate", "Umpqua Valley", 43.2400, -123.4400,
 "Richard Sommer, a UC Davis student, planted Riesling and other varieties near Roseburg in 1961 and founded what is regarded as Oregon's oldest continuously operating estate winery; he also planted the state's first post-Prohibition Pinot Noir.", cls="Founded 1961", q="approx", producers=["HillCrest"]))
S.append(site("abacela", "us", "Abacela", "estate", "Umpqua Valley", 43.1271, -123.4470,
 "Earl and Hilda Jones searched the West for a climate like Spain's Ribera del Duero and planted Tempranillo here in 1995, Oregon's first. They also pioneered Albariño in the Pacific Northwest.", cls="Founded 1995", producers=["Abacela"]))
S.append(site("cayuse", "us", "Cayuse Vineyards (The Rocks)", "vineyard", "The Rocks District of Milton-Freewater", 45.9640, -118.3817,
 "Christophe Baron noticed the cobblestone fields south of Walla Walla in 1996 and planted the Cailloux vineyard in 1997, farmed biodynamically. Cayuse's Syrahs and Grenaches (Bionic Frog, God Only Knows) became cult wines.", q="approx", producers=["Cayuse", "Horsepower"]))
save_part("p06_oregon", regions=regions, appellations=A, sites=S)
